window.PASSAGES = window.PASSAGES || {};
window.PASSAGES["hkt1-p1"] = {title:"Đoạn tư liệu 1: Tuyên ngôn về thủ tiêu hoàn toàn chủ nghĩa thực dân (1960)",text:"Năm 1960, Đại hội đồng Liên hợp quốc đã thông qua bản Tuyên ngôn về thủ tiêu hoàn toàn chủ nghĩa thực dân, trao trả độc lập cho các quốc gia và dân tộc thuộc địa. Đó là một sự kiện chính trị quan trọng. Như thế, Tuyên ngôn đã khẳng định các nước thực dân đã vi phạm nguyên tắc quan trọng nhất của luật pháp quốc tế; khẳng định rõ ràng cơ sở pháp lí quốc tế của cuộc đấu tranh giành độc lập của các dân tộc bị áp bức.\n(Nguyễn Quốc Hùng, Nguyễn Hồng Quân, Liên hợp quốc và Lực lượng gìn giữ hòa bình Liên hợp quốc, NXB Chính trị Quốc gia, Hà Nội, 2008, tr.46)"};
window.PASSAGES["hkt1-p2"] = {title:"Đoạn tư liệu 2: Nguyên nhân sự sụp đổ Trật tự thế giới hai cực I-an-ta",text:"- Chạy đua vũ trang khiến cả Liên Xô và Mỹ bị tốn kém, suy giảm thế mạnh kinh tế, buộc hai bên phải tự điều chỉnh, từng bước hạn chế căng thẳng.\n- Sự vươn lên của các nước trên thế giới nhằm thoát khỏi ảnh hưởng của hai cực.\n- Thắng lợi của phong trào giải phóng dân tộc và sự ra đời của hàng loạt các quốc gia độc lập.\n- Sự thay đổi trong cán cân kinh tế thế giới, đặc biệt là sự nổi lên của Nhật Bản và các nước Tây Âu.\n- Xu thế hòa hoãn, toàn cầu hóa và ảnh hưởng của cuộc Cách mạng công nghiệp lần thứ ba.\n- Sự khủng hoảng, suy yếu rồi tan rã của Liên Xô — quốc gia đứng đầu hệ thống xã hội chủ nghĩa."};
window.PASSAGES["hkt1-p3"] = {title:"Đoạn tư liệu 3: Thắng lợi của cách mạng Trung Quốc năm 1949",text:"Thắng lợi của cách mạng Trung Quốc năm 1949 đã mở ra bước đột phá đầu tiên, phá vỡ âm mưu khống chế Trung Quốc của Mỹ và những đặc quyền của Liên Xô ở vùng Đông Bắc Trung Quốc. Đồng thời, sự lớn mạnh của các nước Tây Âu, Nhật Bản cũng làm suy giảm vị trí và ảnh hưởng của Mỹ trong hệ thống tư bản chủ nghĩa.\n(Theo Lịch sử thế giới hiện đại, Quyển 2, NXB Đại học sư phạm, 2016, tr.94)"};
window.PASSAGES["hkt1-p4"] = {title:"Đoạn tư liệu 4: ASEAN — giáo dục và phát triển nguồn nhân lực",text:"Trong lĩnh vực giáo dục và đào tạo, ASEAN khuyến khích phát triển giáo dục suốt đời, sử dụng công nghệ thông tin và truyền thông (ICT) như những phương tiện thúc đẩy nền giáo dục ASEAN và nâng cao nhận thức về ASEAN. Các dự án khác nhau dành cho các cấp học ở phổ thông và đại học cũng cần được thực hiện nhằm phát triển và nâng cao chất lượng nguồn nhân lực cho các nước thành viên, đặc biệt là nguồn nhân lực trẻ, khẳng định vai trò tiên phong của thanh niên trong việc tham gia xây dựng Cộng đồng ASEAN.\n(Lương Ninh, Đông Nam Á — Lịch sử từ nguyên thủy đến ngày nay, NXB Chính trị quốc gia, Hà Nội, 2015, tr.932)"};
window.PASSAGES["hkt1-p5"] = {title:"Đoạn tư liệu 5: Trật tự thế giới mới sau Chiến tranh lạnh",text:"Trật tự thế giới mới này được hình thành như thế nào, còn phụ thuộc ở nhiều nhân tố: sự phát triển về thực lực kinh tế, chính trị, quân sự của các cường quốc Mĩ, Nga, Trung Quốc, Anh, Pháp, Nhật Bản, Đức, của chạy đua về sức mạnh quốc gia tổng hợp; sự lớn mạnh của phong trào cách mạng thế giới (sự thành bại của công cuộc cải cách, đổi mới ở các nước xã hội chủ nghĩa); sự phát triển của cách mạng khoa học – kĩ thuật sẽ còn tiếp tục tạo ra những đột phá và biến chuyển trên cục diện thế giới.\n(Nguyễn Anh Thái (Chủ biên), Lịch sử thế giới hiện đại, NXB Giáo dục Việt Nam, Hà Nội, 2021, tr.424)"};
window.PASSAGES["hkt1-p6"] = {title:"Đoạn tư liệu 6: Tuyên bố ASEAN (trích)",text:"1. Thúc đẩy sự tăng trưởng kinh tế, tiến bộ xã hội và phát triển văn hoá trong khu vực thông qua các nỗ lực chung trên tinh thần bình đẳng và hợp tác nhằm tăng cường cơ sở cho một Cộng đồng các quốc gia Đông Nam Á hòa bình và thịnh vượng.\n2. Thúc đẩy hòa bình và ổn định khu vực bằng việc tôn trọng công lí và nguyên tắc luật pháp trong quan hệ giữa các quốc gia trong vùng và tuân thủ các nguyên tắc của Hiến chương Liên hợp quốc.\n3. Thúc đẩy sự cộng tác tích cực và giúp đỡ lẫn nhau trong các vấn đề cùng quan tâm trong các lĩnh vực kinh tế, xã hội, văn hoá, khoa học – kĩ thuật và hành chính...\n(Tuyên bố ASEAN, NXB Chính trị Quốc gia, 1998, tr.15-16)"};
